#Requires -Version 5.1
<#
.SYNOPSIS
  Kaira Autonomous Agent - Windows Bootstrap Script
.DESCRIPTION
  Reconstructs the complete local Kaira Agent runtime from an embedded archive.
  No internet download required - all source files are embedded in this script.
.EXAMPLE
  .\bootstrap-kaira-windows.ps1
  .\bootstrap-kaira-windows.ps1 -Destination "C:\Projects\KairaAgent"
#>
[CmdletBinding()]
param(
  [string]$Destination = "$env:USERPROFILE\KairaAgent",
  [switch]$Force
)

$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

function Write-Section($title) {
  Write-Host "`n$('=' * 60)" -ForegroundColor Cyan
  Write-Host "  $title" -ForegroundColor Cyan
  Write-Host "$('=' * 60)" -ForegroundColor Cyan
}
function Write-Ok($msg) { Write-Host "  [OK] $msg" -ForegroundColor Green }
function Write-Warn($msg) { Write-Host "  [WARN] $msg" -ForegroundColor Yellow }
function Write-Err($msg) { Write-Host "  [ERROR] $msg" -ForegroundColor Red }
function Write-Info($msg) { Write-Host "  $msg" -ForegroundColor Gray }

$ArchiveBase64 = @'


'@

Write-Section "Kaira Autonomous Agent - Windows Bootstrap"

# 1. Prerequisites
Write-Section "1. Checking prerequisites"

$nodeOk = $false
try {
  $nodeVersion = (node --version 2>$null)
  if ($nodeVersion -and $nodeVersion -match "v(\d+)") {
    $major = [int]$Matches[1]
    if ($major -ge 18) { Write-Ok "Node.js $nodeVersion found"; $nodeOk = $true }
    else { Write-Warn "Node.js $nodeVersion found but v18+ recommended" }
  }
} catch {}
if (-not $nodeOk) { Write-Err "Node.js not found. Install from https://nodejs.org"; exit 1 }

try { $npmVersion = (npm --version 2>$null); Write-Ok "npm v$npmVersion found" }
catch { Write-Err "npm not found"; exit 1 }

$ollamaOk = $false; $ollamaModels = @()
try {
  $r = (Invoke-RestMethod -Uri "http://localhost:11434/api/tags" -TimeoutSec 5 -ErrorAction Stop)
  $ollamaModels = $r.models | ForEach-Object { $_.name }
  Write-Ok "Ollama is running - $($ollamaModels.Count) model(s) available"
  $ollamaOk = $true
} catch { Write-Warn "Ollama not reachable at http://localhost:11434"; Write-Info "Start: ollama serve | Install: https://ollama.com/download" }

$requiredModels = @("qwen3:8b","qwen2.5-coder:7b","llama3.2:3b")
if ($ollamaOk) {
  Write-Host ""; Write-Info "Checking required models:"
  foreach ($m in $requiredModels) {
    if ($ollamaModels -contains $m) { Write-Ok "Model $m available" }
    else { Write-Warn "Model $m NOT found - run: ollama pull $m" }
  }
}

$pgOk = $false
try { $pgVersion = (psql --version 2>$null); if ($pgVersion) { Write-Ok "PostgreSQL client found: $pgVersion"; $pgOk = $true } }
catch {}
if (-not $pgOk) {
  Write-Warn "PostgreSQL not found in PATH"
  Write-Info "Install from: https://www.postgresql.org/download/windows/"
  Write-Info "Add PostgreSQL bin folder to PATH after install"
}

# 2. Destination
Write-Section "2. Setting up project directory"
if (Test-Path $Destination) {
  if (-not $Force) {
    Write-Warn "Directory exists: $Destination"
    $confirm = Read-Host "  Overwrite? (y/N)"
    if ($confirm -ne "y" -and $confirm -ne "Y") { Write-Host "  Aborted."; exit 0 }
  }
  Remove-Item $Destination -Recurse -Force
}
New-Item -ItemType Directory -Path $Destination -Force | Out-Null
Write-Ok "Created: $Destination"

# 3. Extract
Write-Section "3. Extracting Kaira Agent source files"
$tempTar = Join-Path $env:TEMP "kaira-export.tar.gz"
try {
  [System.IO.File]::WriteAllBytes($tempTar, [System.Convert]::FromBase64String($ArchiveBase64))
  Write-Ok "Decoded embedded archive"
} catch { Write-Err "Failed to decode: $_"; exit 1 }

try {
  Push-Location $Destination
  tar xzf $tempTar --strip-components=1 2>$null
  Pop-Location
  Write-Ok "Extracted source files"
} catch { Write-Err "Failed to extract: $_"; Write-Info "Requires Windows 10 1803+"; exit 1 }
finally { Remove-Item $tempTar -Force -ErrorAction SilentlyContinue }

$fileCount = (Get-ChildItem -Path $Destination -Recurse -File | Measure-Object).Count
Write-Info "$fileCount files extracted"

# 4. Workspace
$workspaceDir = Join-Path $Destination "workspace"
New-Item -ItemType Directory -Path $workspaceDir -Force | Out-Null
Write-Ok "Workspace: $workspaceDir"

# 5. .env
Write-Section "4. Creating configuration"
$envFile = Join-Path $Destination ".env"
$tplFile = Join-Path $Destination ".env.template"
if (Test-Path $tplFile) {
  $envContent = Get-Content $tplFile -Raw
  $envContent = $envContent -replace "YOUR_PASSWORD", "postgres"
  [System.IO.File]::WriteAllText($envFile, $envContent)
  Write-Ok ".env created (default password: postgres)"
  Write-Warn "Edit .env to set your actual PostgreSQL password!"
} else { Write-Warn ".env.template not found" }

# 6. npm install
Write-Section "5. Installing npm dependencies"
Push-Location $Destination
try {
  Write-Info "Running npm install..."
  npm install 2>&1 | ForEach-Object { Write-Host "  $_" -ForegroundColor DarkGray }
  if ($LASTEXITCODE -eq 0) { Write-Ok "npm install completed" }
  else { Write-Warn "npm install had issues - run 'npm install' manually" }
} catch { Write-Warn "npm install failed" }
finally { Pop-Location }

# 7. Database
Write-Section "6. Database setup"
if ($pgOk) {
  Write-Info "Creating database 'kaira_agent'..."
  try {
    $exists = psql -U postgres -tAc "SELECT 1 FROM pg_database WHERE datname='kaira_agent'" 2>$null
    if ($exists -match "1") { Write-Ok "Database 'kaira_agent' exists" }
    else {
      psql -U postgres -c "CREATE DATABASE kaira_agent" 2>$null
      if ($LASTEXITCODE -eq 0) { Write-Ok "Database 'kaira_agent' created" }
      else { Write-Warn "Auto-create failed"; Write-Info "Manual: psql -U postgres -c ""CREATE DATABASE kaira_agent""" }
    }
  } catch { Write-Warn "Cannot connect to PostgreSQL"; Write-Info "Ensure service is running" }

  Push-Location $Destination
  Write-Info "Pushing database schema..."
  npx drizzle-kit push 2>&1 | ForEach-Object { Write-Host "  $_" -ForegroundColor DarkGray }
  if ($LASTEXITCODE -eq 0) { Write-Ok "Schema pushed" }
  else { Write-Warn "Schema push failed - run 'npx drizzle-kit push' manually" }
  Pop-Location
} else {
  Write-Warn "PostgreSQL not detected - database setup skipped"
  Write-Info "After installing PostgreSQL:"
  Write-Info "  1. Create: psql -U postgres -c ""CREATE DATABASE kaira_agent"""
  Write-Info "  2. Edit .env with your password"
  Write-Info "  3. Push schema: npx drizzle-kit push"
}

# 8. Summary
Write-Section "7. Bootstrap Complete!"
Write-Host ""
Write-Host "  Project:    $Destination" -ForegroundColor White
Write-Host "  Workspace:  $workspaceDir" -ForegroundColor White
Write-Host ""
if (-not $ollamaOk) {
  Write-Host "  Start Ollama:  ollama serve" -ForegroundColor Yellow
  Write-Host "  Pull models:" -ForegroundColor Yellow
  Write-Host "    ollama pull qwen3:8b" -ForegroundColor Yellow
  Write-Host "    ollama pull qwen2.5-coder:7b" -ForegroundColor Yellow
  Write-Host "    ollama pull llama3.2:3b" -ForegroundColor Yellow
  Write-Host ""
}
if (-not $pgOk) {
  Write-Host "  Install PostgreSQL and create 'kaira_agent' database" -ForegroundColor Yellow
  Write-Host "  Edit .env with your password" -ForegroundColor Yellow
  Write-Host "  Run: npx drizzle-kit push" -ForegroundColor Yellow
  Write-Host ""
}
Write-Host "  Start Kaira:" -ForegroundColor Green
Write-Host "    cd $Destination" -ForegroundColor White
Write-Host '    npx tsx scripts/run-agent.ts "Create a Python file that prints 12 and verify it"' -ForegroundColor White
Write-Host ""
Write-Host "  Run tests:" -ForegroundColor Green
Write-Host "    npx tsc --noEmit          # Typecheck" -ForegroundColor White
Write-Host "    npx tsx scripts/test-kernel.ts   # Phase 1" -ForegroundColor White
Write-Host "    npx tsx scripts/test-phase2.ts  # Phase 2" -ForegroundColor White
Write-Host "    npx tsx scripts/test-phase3.ts  # Phase 3" -ForegroundColor White
Write-Host "    npx tsx scripts/test-ollama.ts  # Ollama" -ForegroundColor White
Write-Host "    npx tsx scripts/selftest.ts     # Selftest" -ForegroundColor White
Write-Host ""
Write-Host "  Configure:" -ForegroundColor Magenta
Write-Host "    Edit $Destination\.env" -ForegroundColor White
Write-Host "    Set DATABASE_URL with your PostgreSQL password" -ForegroundColor White
Write-Host ""
